        "correctIndex": 1,
        "explanation": "NHANES (National Health and Nutrition Examination Survey) and BRFSS are examples of cross-sectional studies — they measure both exposure and outcome simultaneously, like a 'snapshot in time.' Cross-sectional studies are efficient and inexpensive, and are well-suited for estimating prevalence. They cannot establish causality because the temporal relationship (which came first, exposure or outcome?) cannot be determined. NHANES data is used for nationally representative estimates of nutrition and health.",
