        "correctIndex": 2,
        "explanation": "Criterion validity measures the extent to which an instrument produces accurate results compared to a gold standard (or criterion). Comparing a new FFQ to a 7-day weighed food record is a classic criterion validity assessment. Face validity is the subjective sense that items 'look right.' Content validity is whether all relevant dimensions of the construct are represented. Construct validity tests whether the instrument distinguishes between related but different constructs.",
