        "id": "m2-entp-016",
        "domain": "Domain II",
        "topic": "Parenteral Nutrition Calculations",
        "difficulty": "hard",
        "text": "A patient weighing 80 kg receives 2,400 mL of D15W (15% dextrose) over 24 hours. What is the glucose infusion rate (GIR) in mg/kg/min?",
        "options": [
            "1.25 mg/kg/min",
            "2.08 mg/kg/min",
            "3.13 mg/kg/min",
            "4.50 mg/kg/min"
        ],
        "correctIndex": 2,
        "explanation": "Step 1: Dextrose grams = 2,400 mL × 15 g/100 mL = 360 g. Step 2: Convert to mg: 360,000 mg. Step 3: GIR = 360,000 mg ÷ (80 kg × 1,440 min/day) = 360,000 ÷ 115,200 = 3.13 mg/kg/min. This is within the safe limit of ≤4 mg/kg/min. If GIR exceeded 4–5 mg/kg/min, the patient would be at risk for hyperglycemia, fatty liver, and excess CO2 production.",
