export async function getQuestions(moduleId?: string, limit = 10): Promise<Question[]> {
    await new Promise(resolve => setTimeout(resolve, 300));
    let start = [...SAMPLE_QUESTIONS];

    if (moduleId) {
        const domainMap: Record<string, string> = {
            '1': 'Domain I',
            '2': 'Domain II',
            '3': 'Domain III',
            '4': 'Domain IV'
        };
        const dLabel = domainMap[moduleId];
        if (dLabel) {
            start = start.filter(q => q.domain.startsWith(dLabel));
        }
    }

    for (let i = start.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [start[i], start[j]] = [start[j], start[i]];
    }

    return start.slice(0, limit);
}

export async function getAllQuestions(): Promise<Question[]> {
    return SAMPLE_QUESTIONS;
}

export async function getQuestionsByIds(ids: string[]): Promise<Question[]> {
    return SAMPLE_QUESTIONS.filter(q => ids.includes(q.id));
}
